anModal')">Cancel</button><button class="btn btn-primary">Save Plan</button></div></form></div></div>
<div class="modal-overlay" id="scheduleModal"><div class="modal-content"><div class="modal-header"><div style="display:flex;align-items:center;gap:.5rem">@include('partials.modal_logo')<h3 class="modal-title">Schedule Price Change</h3></div><button class="modal-close" type="button" onclick="closeModal('scheduleModal')">&times;</button></div><form method="POST" action="{{ route('price.management') }}">@csrf<input type="hidden" name="action" value="schedule"><input type="hidden" name="plan_id" id="scheduledPlanId"><p id="scheduledPlanName" style="color:var(--text-muted);margin-top:0"></p><div class="form-grid"><div class="form-group"><label class="form-label">New Monthly Price (₱) *</label><input class="form-input" type="number" step="0.01" min="0" name="scheduled_monthly_price" id="scheduledMonthlyPrice" required></div><div class="form-group"><label class="form-label">New Installation Fee (₱) *</label><input class="form-input" type="number" step="0.01" min="0" name="scheduled_installation_fee" id="scheduledInstallationFee" required></div><div class="form-group"><label class="form-label">Effective Date *</label><input class="form-input" type="date" name="price_effective_on" id="priceEffectiveOn" required></div><div class="form-group"><label class="form-label">Reason *</label><input class="form-input" name="reason" required maxlength="1000"></div></div><p style="color:var(--text-muted);font-size:.85rem">This change affects future registrations and future plan changes only. Existing clients retain their recorded rate.</p><div style="display:flex;justify-content:flex-end;gap:1rem"><button type="button" class="btn btn-secondary" onclick="closeModal('scheduleModal')">Cancel</button><button class="btn btn-primary">Schedule Change</button></div></form></div></div>
<script>
function openModal(id){document.getElementById(id).classList.add('active')} function closeModal(id){document.getElementById(id).classList.remove('active')}
function openPlanModal(p=null){openModal('planModal');modalTitle.textContent=p?'Edit Internet Plan':'Add Internet Plan';formAction.value=p?'update':'create';planId.value=p?p.id:'';planName.value=p?p.plan_name:'';speedMbps.value=p?p.speed_mbps:'';monthlyPrice.value=p?p.monthly_price:'';installationFee.value=p?p.installation_fee:'';description.value=p?(p.description||''):'';planStatus.value=p?p.status:'active';planReason.value=''}
function openScheduleModal(p){scheduledPlanId.value=p.id;scheduledPlanName.textContent=p.plan_name+' — current monthly rate: ₱'+Number(p.monthly_price).toFixed(2);scheduledMonthlyPrice.value=p.scheduled_monthly_price||p.monthly_price;scheduledInstallationFee.value=p.scheduled_installation_fee||p.installation_fee;priceEffectiveOn.value=p.price_effective_on||'';openModal('scheduleModal')}
document.querySelectorAll('.modal-overlay').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.modal-overlay.active').forEach(m=>closeModal(m.id));closePlanActionMenus()}});
function closePlanActionMenus(){document.querySelectorAll('.action-menu-dropdown.show').forEach(menu=>{menu.classList.remove('show');if(menu._planMenuPlaceholder){menu.removeAttribute('style');menu._planMenuPlaceholder.replaceWith(menu);delete menu._planMenuPlaceholder}});document.querySelectorAll('.action-menu-btn[aria-expanded="true"]').forEach(button=>button.setAttribute('aria-expanded','false'))}
function togglePlanActionMenu(button){const menu=button.nextElementSibling;const willOpen=!menu.classList.contains('show');closePlanActionMenus();if(!willOpen)return;const placeholder=document.createComment('plan action menu');menu.parentNode.replaceChild(placeholder,menu);menu._planMenuPlaceholder=placeholder;document.body.appendChild(menu);menu.style.cssText='position:fixed;visibility:hidden;z-index:1000;right:auto;bottom:auto';menu.classList.add('show');const buttonRect=button.getBoundingClientRect(),menuRect=menu.getBoundingClientRect();const top=buttonRect.top>=menuRect.height+8?buttonRect.top-menuRect.height-6:Math.min(window.innerHeight-menuRect.height-8,buttonRect.bottom+6);const left=Math.max(8,Math.min(window.innerWidth-menuRect.width-8,buttonRect.right-menuRect.width));menu.style.top=Math.max(8,top)+'px';menu.style.left=left+'px';menu.style.visibility='visible';button.setAttribute('aria-expanded','true')}
document.addEventListener('click',event=>{if(!event.target.closest('.action-menu')&&!event.target.closest('.action-menu-dropdown'))closePlanActionMenus()});
</script><script src="{{ asset('js/jftech-main.js') }}?{{ $mainJsVersion }}"></script></body></html>
